    "code": "\r\ndocument.addEventListener('DOMContentLoaded', function() {\r\n    var modal = document.getElementById('world-say-popup-modal7');\r\n    var iframe = modal.querySelector('iframe');\r\n\r\n    // Bootstrap modal event (if Bootstrap is used)\r\n    modal.addEventListener('hidden.bs.modal', function () {\r\n        // clear src to stop video\r\n        iframe.src = '';\r\n    });\r\n\r\n    // If the modal can be reopened, restore src on show\r\n    modal.addEventListener('show.bs.modal', function () {\r\n        iframe.src = iframe.dataset.src;\r\n    });\r\n\r\n    // Store initial src in data attribute\r\n    iframe.dataset.src = iframe.src;\r\n});\r\n"
